WITH valid_departments AS (SELECT *, CASE WHEN dept_name IN ('Engineering', 'Finance') THEN 'Group A' ELSE 'Other' END AS dept_name_group FROM departments WHERE dept_name IN ('Finance', 'HR')), Agg AS (SELECT dept_name, SORT_ARRAY(COLLECT_SET(location)) AS location_list, MAX(budget) AS max_budget FROM valid_departments GROUP BY dept_name) SELECT dept_name, location_list FROM Agg ORDER BY dept_name DESC LIMIT 1;
